package com.cpf.batch.agent; import com.cpf.batch.agent.internal.*; import org.springframework.context.annotation.*; import org.springframework.web.client.RestClient;
@Configuration public class AgentConfiguration { @Bean ArtifactVerifier artifactVerifier(AgentProperties p){return new ArtifactVerifier(p);}@Bean ArtifactInstaller artifactInstaller(AgentProperties p,ArtifactVerifier v){return new ArtifactInstaller(p,v);}@Bean ServiceManager serviceManager(AgentProperties p){return new ServiceManager(p);}@Bean RuntimeControlProxy runtimeControlProxy(AgentProperties p,RestClient.Builder b){return new RuntimeControlProxy(p,b);}@Bean LogArchiveService logArchiveService(AgentProperties p){return new LogArchiveService(p);}@Bean AgentProductionSafetyValidator safety(org.springframework.core.env.Environment e,AgentProperties p){return new AgentProductionSafetyValidator(e,p);} }
